<?php declare(strict_types=1); namespace App\Modules\Tourism\Services; use App\Modules\Tourism\Models\TourismReview; final class TourismReviewService{private TourismReview $m;public function __construct(){$this->m=new TourismReview();}public function all(int $t):array{return $this->m->all($t);}public function status(int $t,int $id,string $s):void{if(!in_array($s,['Pending','Approved','Rejected','Hidden'],true))throw new \RuntimeException('Invalid review status.');$this->m->status($t,$id,$s);}}
